import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-07-01 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-07-01 :: Ceph Orchestration Meeting","date":"2019-07-01T00:00:00.000Z","updated":"2019-07-04T00:00:00.000Z","tags":["Ceph","Orchestrator","Python代码统一","API生成","Drive Groups"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-01_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-07-01_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-07-01_-_-_Ceph_Orchestration_Meeting.md"};function n(p,t,l,a,h,_){return e(),r("div",null,[...t[0]||(t[0]=[s("<p>会议纪要：</p><p><strong>会议时间</strong>： 2019年7月（具体日期未提及）</p><p><strong>参会人员</strong>： Joan Miguel, Takata, Billy, Nick Payne, Patrick Connelly, Frida, Taste, Element等</p><p><strong>会议主题</strong>： Ceph社区讨论，包括Python代码统一、API生成、Orchestrator功能、SD移除、Rook与Ceph的集成、Drive Groups等。</p><p><strong>会议关键细节</strong>：</p><ul><li><strong>Python代码统一</strong>： 讨论了将Ceph中分散的Python代码统一到一个地方的提案，以减少代码重复并提高代码质量。提议得到积极响应，但需要更多人反馈。</li><li><strong>API生成</strong>： 讨论了API生成的问题，包括何时触发API生成、API生成后的测试等。决定在API发生变化时触发生成，并要求API变更者负责重建文件和提交新生成的API方法。</li><li><strong>Orchestrator功能</strong>： 讨论了Orchestrator的功能，包括SD移除、替换OSD等。认为目前SD移除的代码不够清晰，可能存在性能问题。</li><li><strong>Rook与Ceph的集成</strong>： 讨论了Rook与Ceph的集成，包括如何处理SD移除、替换OSD等。认为Rook需要更好的支持Ceph的驱动组功能。</li><li><strong>Drive Groups</strong>： 讨论了Drive Groups的功能和实现方式，认为将其集成到Ceph Volume中可以简化操作并提高效率。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>推进Python代码统一的提案，并邀请更多社区成员参与反馈。</li><li>完善API生成机制，确保API生成的正确性和可靠性。</li><li>优化Orchestrator的功能，提高代码质量和性能。</li><li>加强Rook与Ceph的集成，提高Rook对Ceph功能的支持。</li><li>探索将Drive Groups集成到Ceph Volume中的可能性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续讨论并完善Python代码统一的提案。</li><li>开发API生成工具，并编写相应的测试用例。</li><li>优化Orchestrator的功能，并修复相关bug。</li><li>与Rook社区合作，改进Rook对Ceph功能的支持。</li><li>探索将Drive Groups集成到Ceph Volume中的可能性。</li></ul><p><strong>其他</strong>：</p><ul><li>提到了Ceph社区每周会议和每月上游会议，鼓励大家积极参与。</li></ul><p><strong>关键词</strong>： Python代码统一、API生成、Orchestrator、SD移除、Rook、Drive Groups、Ceph Volume</p>",13)])])}const u=o(i,[["render",n]]);export{c as __pageData,u as default};
